function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function rub(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,' ')+' ₽'; }

/* ============ КАРТЫ: ПОДСВЕТКА МАРШРУТА ============ */
var X0=104, X1=792, SEA=216;
function rayD(mid,a,b){
  var xa=X0+(X1-X0)*a/100, xb=X0+(X1-X0)*b/100, T=15;
  return 'M 986 88 L '+xa+' '+(SEA-T)+' L '+xa+' '+(SEA+T)+' L '+xb+' '+(SEA+T)+' L '+xb+' '+(SEA-T)+' L 986 100 Z';
}
function litTo(mid,a,b){
  var lit=document.getElementById('lit'+mid), ray=document.getElementById('ray'+mid);
  if(ray) ray.setAttribute('d',rayD(mid,a,b));
  if(!lit) return;
  lit.style.transition='none';
  lit.setAttribute('stroke-dashoffset',-a);
  lit.setAttribute('stroke-dasharray','0 100');
  requestAnimationFrame(function(){ requestAnimationFrame(function(){
    lit.style.transition=REDUCE?'none':'stroke-dasharray .85s cubic-bezier(.32,.72,0,1)';
    lit.setAttribute('stroke-dasharray',(b-a)+' 100');
  });});
}
function initMaps(){
  ['R','B'].forEach(function(m){ if(document.getElementById('lit'+m)) litTo(m,0,100); });
  document.querySelectorAll('.chip[data-map]').forEach(function(c){
    function on(){
      var m=c.dataset.map;
      document.querySelectorAll('.chip[data-map="'+m+'"]').forEach(function(x){ x.classList.toggle('on',x===c); });
      litTo(m,+c.dataset.a,+c.dataset.b);
    }
    c.addEventListener('mouseenter',on); c.addEventListener('focus',on);
  });
}

