function svDraw(i,dir){
  var tr=document.getElementById('svTrack'); if(!tr) return;
  var bar=document.getElementById('svBar');
  if(i>=SURVEY.length){
    tr.innerHTML='<div class="qcard in-a"><div class="qdone"><b>Спасибо, этого достаточно</b>'+
      '<span class="small" style="color:#1D5C42">Ответы уйдут вместе с заявкой — проверим внимательнее там, где Вы отметили риск.</span></div>'+
      '<div class="qnav"><button class="qback" type="button" data-sv="back">← К последнему вопросу</button></div></div>';
    if(bar) bar.style.width='100%';
    return;
  }
  var q=SURVEY[i], cur=svState[q.n];
  tr.innerHTML='<div class="qcard in-a"><div class="qmeta"><span class="qnum">Вопрос '+q.n+' из '+SURVEY.length+'</span>'+
    '<button class="qskip" type="button" data-sv="skip">Пропустить →</button></div>'+
    '<div class="qq">'+esc(q.q)+'</div>'+(q.h?'<div class="qh">'+esc(q.h)+'</div>':'')+
    '<div class="qopts">'+q.a.map(function(a){ return '<button class="qopt'+(cur===a?' on':'')+'" type="button" data-a="'+esc(a)+'">'+esc(a)+'</button>'; }).join('')+'</div>'+
    (q.own?'<div class="qown"><input type="text" placeholder="'+esc(q.own)+'" data-svown value="'+esc(svState[q.n+'_own']||'')+'"></div>':'')+
    '<div class="qnav"><button class="qback" type="button" data-sv="back"'+(i?'':' disabled')+'>← Назад</button>'+
    '<span class="qprog">Отвечено: '+Object.keys(svState).filter(function(k){ return k.indexOf('_own')<0; }).length+' из '+SURVEY.length+'</span></div></div>';
  tr.dataset.i=i;
  if(bar) bar.style.width=Math.round(i*100/SURVEY.length)+'%';
}
document.addEventListener('click',function(e){
  var t=e.target.closest('#svToggle');
  if(t){ var b=document.getElementById('svBox'); b.classList.toggle('open');
    if(b.classList.contains('open')&&!document.getElementById('svTrack').childNodes.length) svDraw(0); return; }
  var tr=document.getElementById('svTrack'); if(!tr) return;
  var i=+(tr.dataset.i||0);
  var o=e.target.closest('.qopt');
  if(o&&tr.contains(o)){ svState[SURVEY[i].n]=o.dataset.a; svDraw(i+1); return; }
  var n=e.target.closest('[data-sv]');
  if(n&&tr.contains(n)){
    if(n.dataset.sv==='skip') svDraw(i+1);
    else svDraw(Math.max(0,(tr.querySelector('.qdone')?SURVEY.length:i)-1));
  }
});

