/* ============ ESTATE API / ЮKassa ============ */
var ESTATE_API='https://d5d7m3j4ab9b3r18lbml.uvah0e6r.apigw.yandexcloud.net';
var API_PAY_SKUS={ 'obj-fast':1, 'obj-deep':1, 'obj-full':1 };
function guessContentType(file){
  if(file.type) return file.type;
  var n=(file.name||'').toLowerCase();
  if(n.endsWith('.pdf')) return 'application/pdf';
  if(n.endsWith('.png')) return 'image/png';
  if(n.endsWith('.jpg')||n.endsWith('.jpeg')) return 'image/jpeg';
  if(n.endsWith('.doc')) return 'application/msword';
  if(n.endsWith('.docx')) return 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
  if(n.endsWith('.txt')) return 'text/plain';
  return 'application/octet-stream';
}
function apiJson(path, opts){
  opts=opts||{};
  var headers={};
  if(opts.body) headers['Content-Type']='application/json';
  return fetch(ESTATE_API+path, {
    method: opts.method||'GET',
    headers: headers,
    body: opts.body ? JSON.stringify(opts.body) : undefined
  }).then(function(res){
    return res.text().then(function(text){
      var data=null;
      try{ data=text ? JSON.parse(text) : null; }catch(err){ data={ raw:text }; }
      if(!res.ok){
        var msg=(data&&(data.message||data.error||data.detail))||('Ошибка API '+res.status);
        throw new Error(typeof msg==='string'?msg:JSON.stringify(msg));
      }
      return data||{};
    });
  });
}
/* ============ БЕСПЛАТНЫЙ РАЗБОР ОБЪЯВЛЕНИЯ ============ */
/* Приём ссылки, опрос статуса и показ готового отчёта. Контракт, коды ответов и
   поведение описаны в документе «Сервис разбора объявлений». Ссылка на отчёт
   открывается обычной ссылкой в новой вкладке: это presigned-адрес хранилища,
   скриптом его не забрать, а всплывающее окно браузер заблокирует — с момента
   нажатия проходят минуты. */
var AD_HOSTS=['avito.ru','cian.ru','domclick.ru','realty.yandex.ru','realty.ya.ru'];
var AD_POLL_MS=5000, AD_GIVEUP_MS=5*60*1000;
var AD_TXT={
  badUrl:'Похоже, это не ссылка. Скопируйте адрес объявления целиком.',
  badHost:'Мы разбираем объявления с Авито, Циан, Домклик и Яндекс Недвижимости. Пришлите ссылку с одной из этих площадок.',
  badEmail:'Проверьте адрес почты — кажется, в нём опечатка.',
  often:'Сейчас слишком много запросов. Подождите минуту и отправьте ссылку ещё раз.',
  net:'Не получилось связаться с сервисом. Проверьте интернет и попробуйте ещё раз.',
  lost:'Заявка не найдена. Отправьте ссылку на объявление заново.',
  slow:'Разбор занимает больше обычного. Попробуйте обновить страницу через несколько минут или пришлите ссылку ещё раз.',
  wait:'Читаем объявление и фотографии'
};
function adHost(raw){
  try{
    var u=new URL(String(raw).trim());
    if(u.protocol!=='http:'&&u.protocol!=='https:') return null;
    return u.hostname.toLowerCase().replace(/^www\./,'');
  }catch(x){ return null; }
}
function adSupported(raw){
  var h=adHost(raw); if(!h) return false;
  for(var i=0;i<AD_HOSTS.length;i++){
    if(h===AD_HOSTS[i]||h.slice(-(AD_HOSTS[i].length+1))==='.'+AD_HOSTS[i]) return true;
  }
  return false;
}
/* Ответ нужен целиком: у кода 429 два разных смысла — дневной лимит клиента и
   общий лимит сервиса, — и различить их можно только по телу. */
function adApi(path,opts){
  opts=opts||{};
  var headers={};
  if(opts.body) headers['Content-Type']='application/json';
  return fetch(ESTATE_API+path,{
    method:opts.method||'GET', headers:headers,
    body:opts.body?JSON.stringify(opts.body):undefined
  }).then(function(res){
    return res.text().then(function(text){
      var data=null;
      try{ data=text?JSON.parse(text):{}; }catch(err){ data={}; }
      return {status:res.status,data:data||{}};
    });
  });
}
function adError(res){
  var d=res.data||{};
  if(res.status===429) return (d.error==='daily_limit'&&d.message)?d.message:AD_TXT.often;
  if(d.error==='host_not_allowed') return AD_TXT.badHost;
  if(d.error==='bad_url') return AD_TXT.badUrl;
  if(d.error==='bad_email') return AD_TXT.badEmail;
  return d.message||AD_TXT.net;
}
function adPoll(id,onTick){
  var started=Date.now();
  return new Promise(function(resolve,reject){
    (function tick(){
      if(Date.now()-started>AD_GIVEUP_MS){ reject(new Error(AD_TXT.slow)); return; }
      adApi('/api/listing-status?listing_id='+encodeURIComponent(id)).then(function(res){
        var d=res.data;
        if(res.status===404){ reject(new Error(AD_TXT.lost)); return; }
        /* 503 — не отказ по заявке, а недоступное хранилище статусов: ждём дальше */
        if(res.status>=500||d.error==='db_unavailable'){ setTimeout(tick,AD_POLL_MS); return; }
        if(res.status>=400){ reject(new Error(d.message||AD_TXT.net)); return; }
        if(d.status==='DONE'&&d.report_url){ resolve(d.report_url); return; }
        if(d.status==='FAILED'){ reject(new Error(d.message||'Объявление недоступно: похоже, оно снято с публикации.')); return; }
        if(onTick) onTick(Math.round((Date.now()-started)/1000));
        setTimeout(tick,AD_POLL_MS);
      }).catch(function(){ setTimeout(tick,AD_POLL_MS); });
    })();
  });
}
function adDone(f,reportUrl,ageSec,rerun){
  var box=f.querySelector('.form-done'); if(!box) return;
  var when='';
  if(ageSec){
    var d=new Date(Date.now()-ageSec*1000);
    when=('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);
  }
  box.innerHTML='<h4>Разбор готов</h4>'+
    (when?'<p class="small">Это объявление уже разбиралось сегодня. Показываем разбор от '+when+'.</p>':'')+
    '<p><a class="btn b-amber" href="'+esc(reportUrl)+'" target="_blank" rel="noopener">Открыть разбор объявления</a></p>'+
    (when?'<p><button class="btn b2" type="button" data-ad-again>Проверить заново</button></p>':'');
  f.classList.add('sent');
  var again=box.querySelector('[data-ad-again]');
  if(again) again.addEventListener('click',function(){ f.classList.remove('sent'); rerun(true); });
}
function adFail(f,msg){
  var box=f.querySelector('.form-done'); if(!box){ alert(msg); return; }
  box.innerHTML='<h4>Не получилось</h4><p class="small">'+esc(msg)+'</p>';
  f.classList.add('sent');
}
function adRun(f,url,email,force){
  var btn=f.querySelector('.submit'), prev=btn?btn.innerHTML:'';
  function busy(on,label){
    if(!btn) return;
    btn.disabled=!!on; btn.classList.toggle('off',!!on);
    if(on) btn.textContent=label||AD_TXT.wait; else btn.innerHTML=prev;
  }
  function rerun(fc){ adRun(f,url,email,fc); }
  function finish(reportUrl,age){ busy(false); adDone(f,reportUrl,age,rerun); }
  function fail(msg){ busy(false); adFail(f,msg); }
  function wait(id){
    adPoll(id,function(sec){ busy(true,AD_TXT.wait+(sec>20?' · '+sec+' с':'…')); })
      .then(function(u){ finish(u,0); })
      .catch(function(e){ fail((e&&e.message)||AD_TXT.net); });
  }

  if(!adSupported(url)){ adFail(f,adHost(url)?AD_TXT.badHost:AD_TXT.badUrl); return; }
  busy(true,AD_TXT.wait+'…');
  var body={url:url};
  if(email) body.email=email;
  if(force) body.force=true;
  adApi('/api/listing',{method:'POST',body:body}).then(function(res){
    if(res.status>=400||res.data.error){ fail(adError(res)); return; }
    var id=res.data.listing_id;
    if(!id){ fail(AD_TXT.net); return; }
    /* Готовый свежий разбор приходит сразу: только у него есть возраст. */
    if(res.data.reused&&typeof res.data.report_age_sec==='number'){
      var age=res.data.report_age_sec;
      adApi('/api/listing-status?listing_id='+encodeURIComponent(id)).then(function(st){
        if(st.data.status==='DONE'&&st.data.report_url) finish(st.data.report_url,age);
        else wait(id);
      }).catch(function(){ wait(id); });
      return;
    }
    wait(id);
  }).catch(function(){ fail(AD_TXT.net); });
}
/* Из готового отчёта человек приходит на страницу со ссылкой вида ?kn=…&ref=…
   Номер подставляется в форму платной проверки, метка нужна для подсчёта
   конверсии из бесплатного разбора. */
function adRef(){ try{ return localStorage.getItem('mayak_ref')||''; }catch(x){ return ''; } }
function adFromQuery(){
  var q;
  try{ q=new URLSearchParams(location.search||''); }catch(x){ return; }
  var ref=q.get('ref');
  if(ref){ try{ localStorage.setItem('mayak_ref',ref); }catch(x){} }
  var kn=q.get('kn');
  if(!kn) return;
  try{ sessionStorage.setItem('mayak-kn',kn); }catch(x){}
  var hook=document.querySelector('[data-form="svc"][data-svc="obj-fast"]');
  if(hook&&hook.scrollIntoView) hook.scrollIntoView({block:'center',behavior:REDUCE?'auto':'smooth'});
}

function putPresigned(url, file, contentType){
  return fetch(url, {
    method: 'PUT',
    headers: { 'Content-Type': contentType },
    body: file,
    redirect: 'error'
  }).then(function(putRes){
    if(putRes.ok) return putRes;
    return putRes.text().then(function(text){
      var hint='Не удалось загрузить файл в хранилище ('+putRes.status+')';
      if(text&&text.indexOf('SignatureDoesNotMatch')!==-1){
        hint+='. Подпись не совпала: нужен PUT и Content-Type ровно как при создании URL.';
      }
      throw new Error(hint);
    });
  });
}
function waitForPayment(caseId, setBusy){
  var attempts=0, maxAttempts=50, delayMs=2500;
  function once(){
    attempts++;
    if(setBusy) setBusy(true, 'Ждём ссылку на оплату… ('+attempts+'/'+maxAttempts+')');
    return apiJson('/api/status?case_id='+encodeURIComponent(caseId), {method:'GET'}).then(function(st){
      var payStatus=st.payment_status==null ? null : String(st.payment_status).toLowerCase();
      var url=typeof st.confirmation_url==='string' ? st.confirmation_url : '';
      if(payStatus==='succeeded') return { action:'paid' };
      if(payStatus==='canceled'||payStatus==='cancelled'){
        throw new Error('Платёж отменён. Попробуйте оформить заявку ещё раз.');
      }
      if(url && (payStatus==='pending' || payStatus===null)) return { action:'pay', url:url };
      if(payStatus==='pending' || payStatus===null){
        if(attempts>=maxAttempts){
          if(payStatus===null && !url){
            throw new Error('Произошла ошибка при создании оплаты. Попробуйте позже или напишите на sales@mayak-legal.ru');
          }
          throw new Error('Не получили ссылку на оплату вовремя. Попробуйте позже или напишите на sales@mayak-legal.ru');
        }
        return new Promise(function(resolve){ setTimeout(resolve, delayMs); }).then(once);
      }
      if(url) return { action:'pay', url:url };
      if(attempts>=maxAttempts){
        throw new Error('Произошла ошибка при создании оплаты. Попробуйте позже или напишите на sales@mayak-legal.ru');
      }
      return new Promise(function(resolve){ setTimeout(resolve, delayMs); }).then(once);
    });
  }
  return once();
}
function startEstateCase(payload, setBusy){
  var email=payload.email||'';
  var kad=payload.kad||'';
  var addr=payload.addr||'';
  var amount=Number(payload.amount)||0;
  var files=payload.files||[];
  if(!amount||amount<=0) throw new Error('Некорректная сумма оплаты');
  if(setBusy) setBusy(true, 'Создаём заявку…');
  return apiJson('/api/case', {method:'POST'}).then(function(caseData){
    var caseId=caseData.case_id;
    if(!caseId) throw new Error('API не вернул case_id');
    var uploadList=files.slice();
    if(!uploadList.length){
      var text='Заявка Маяк\nУслуга: '+(payload.name||'')+'\nКадастровый номер: '+(kad||'—')+
        '\nАдрес: '+(addr||'—')+'\nПочта: '+email+'\nЗаказ: '+(payload.num||'')+'\n';
      uploadList=[new File([text], 'application.txt', {type:'text/plain'})];
    }
    var registered=[];
    var chain=Promise.resolve();
    uploadList.forEach(function(file){
      chain=chain.then(function(){
        var contentType=guessContentType(file);
        if(setBusy) setBusy(true, 'Загружаем '+file.name+'…');
        return apiJson('/api/upload-url', {
          method:'POST',
          body:{ case_id:caseId, filename:file.name, content_type:contentType }
        }).then(function(up){
          if(!up.url||!up.object_key||!up.doc_id) throw new Error('Некорректный ответ /api/upload-url');
          var putType=up.content_type||contentType;
          return putPresigned(up.url, file, putType).then(function(){
            registered.push({ doc_id:up.doc_id, object_key:up.object_key, filename:file.name, content_type:putType });
          });
        });
      });
    });
    return chain.then(function(){
      if(setBusy) setBusy(true, 'Регистрируем документы…');
      return apiJson('/api/commit', { method:'POST', body:{ case_id:caseId, docs:registered } });
    }).then(function(){
      if(setBusy) setBusy(true, 'Запускаем оплату…');
      return apiJson('/api/start', {
        method:'POST',
        body:{ case_id:caseId, amount:amount, recipient:email }
      });
    }).then(function(){ return caseId; });
  });
}
function applyPaymentResult(result){
  if(result&&result.action==='paid'){ location.href='/payment/result/'; return; }
  if(result&&result.action==='pay'&&result.url){ location.href=result.url; return; }
  throw new Error('Произошла ошибка при создании оплаты. Попробуйте позже или напишите на sales@mayak-legal.ru');
}

/* ------------------------------------------------------------------ *
 *  ЗДЕСЬ ПОДКЛЮЧАЕТСЯ ОТПРАВКА ЗАЯВКИ                                *
 *  Впишите адрес обработчика в SEND_TO — и заявки начнут уходить.    *
 *  Например: var SEND_TO='/send.php';                                *
 *  Пока строка пустая, данные никуда не отправляются.                *
 *  Уходит: название услуги, номер и дата заказа, канал связи,        *
 *  все поля формы и файлы, отметки согласий, ответы анкеты.          *
 * ------------------------------------------------------------------ */
var SEND_TO='';
function sendForm(f,extra){
  if(!SEND_TO) return;
  try{
    var fd=new FormData(f);
    Object.keys(extra||{}).forEach(function(k){ fd.append(k,extra[k]); });
    if(Object.keys(svState).length) fd.append('anketa',JSON.stringify(svState));
    fd.append('page',location.pathname);
    var mkRef=adRef(); if(mkRef) fd.append('ref',mkRef);
    fetch(SEND_TO,{method:'POST',body:fd});
  }catch(x){}
}
document.addEventListener('submit',function(e){
  var f=e.target.closest('.mk-form'); if(!f) return;
  e.preventDefault();
  if(!check(f,true)){
    var bad=f.querySelector('.field.bad input,.field.bad textarea,.field.bad select');
    if(bad) bad.focus();
    else { var ag=f.querySelector('.agree.bad'); if(ag) ag.scrollIntoView({block:'center',behavior:REDUCE?'auto':'smooth'}); }
    return;
  }
  var id=f.id;
  /* Бесплатный разбор объявления: своя цепочка, без заявки и оплаты. */
  if(id==='formAd'||(id==='mForm'&&pending&&pending.kind==='svc'&&pending.key==='ad')){
    var adLink=((f.querySelector('[name="link"]')||{}).value||'').trim();
    var adMail=((f.querySelector('[name="email"]')||{}).value||'').trim();
    adRun(f,adLink,adMail,false);
    return;
  }
  if(id==='mForm'&&pending){
    var dl=f.querySelector('[name="delivery"]:checked');
    if(pending.kind==='pack'&&packRef){
      var sel=f.querySelector('select[name="ptype"]'), k=sel?sel.selectedIndex:0;
      var ps=packRef.svc[k]||packRef.svc[0];
      pending.price=ps.fin; pending.ptxt=rub(ps.fin);
      pending.name='Пакет «'+packRef.n+'» — '+ps.n+', '+packRef.q+' проверок';
    }
    var email=((f.querySelector('[name="email"]')||{}).value||'').trim();
    var kad=((f.querySelector('[name="kad"]')||{}).value||'').trim();
    var addr=((f.querySelector('[name="addr"]')||{}).value||'').trim();
    var fileInput=f.querySelector('[name="docs"]');
    var files=fileInput&&fileInput.files ? Array.prototype.slice.call(fileInput.files) : [];
    order={num:orderNum(),date:nowStr(),name:pending.name,price:pending.price,ptxt:pending.ptxt,
           way:(dl&&dl.value==='tg')?'в Telegram':'на электронную почту',kind:pending.kind,
           svc:pending.key||'', email:email, kad:kad, addr:addr, case_id:null};
    saveOrder();
    sendForm(f,{form:'Заявка на услугу',service:order.name,order:order.num,
                date:order.date,amount:order.ptxt,channel:order.way});

    var apiSku=pending.kind==='svc' && API_PAY_SKUS[pending.key];
    if(apiSku && pending.price>0){
      var btn=f.querySelector('.submit');
      var prevHtml=btn?btn.innerHTML:'';
      function setBusy(on,label){
        if(!btn) return;
        btn.disabled=!!on;
        btn.classList.toggle('off', !!on);
        if(on) btn.textContent=label||'Отправляем…';
        else btn.innerHTML=prevHtml;
      }
      startEstateCase({
        email:email, kad:kad, addr:addr, amount:pending.price,
        files:files, name:pending.name, num:order.num
      }, setBusy).then(function(caseId){
        order.case_id=caseId; saveOrder();
        closeModal();
        go('checkout',true);
      }).catch(function(err){
        setBusy(false);
        alert(((err&&err.message)||'Не удалось создать заявку')+'\n\nПопробуйте ещё раз или напишите на sales@mayak-legal.ru');
      });
      return;
    }

    closeModal();
    if(pending.price>0) go('checkout',true);
    else { go('success',true); }
    return;
  }
  if(id==='formAuth'){ sendForm(f,{form:'Вход в личный кабинет'}); f.classList.add('sent'); setTimeout(lkOpen,700); return; }
  sendForm(f,{form:({formCl:'Запрос чек-листов',formSamples:'Запрос примеров отчётов',
                     formUnsub:'Отписка от рассылок'}[id]||id)});
  f.classList.add('sent');
},true);

