function drawCheckout(){
  var box=document.getElementById('coSum'); if(!box) return;
  if(!order){ order={num:orderNum(),date:nowStr(),name:'Проверка объекта и продавца',price:4450,ptxt:'4 450 ₽',way:'на электронную почту',kind:'svc'}; saveOrder(); }
  box.innerHTML='<div><dt>Услуга</dt><dd>'+esc(order.name)+'</dd></div>'+
    '<div><dt>Номер заказа</dt><dd>'+order.num+'</dd></div>'+
    '<div><dt>Дата и время</dt><dd>'+order.date+'</dd></div>'+
    '<div><dt>Результат придёт</dt><dd>'+order.way+'</dd></div>'+
    '<div><dt>Итого</dt><dd>'+order.ptxt+'</dd></div>';
}
function drawSuccess(){
  if(!document.getElementById('okNum')) return;
  if(!order){ order={num:orderNum(),date:nowStr(),name:'Заказ',price:0,ptxt:'—',way:'на электронную почту',kind:'svc'}; saveOrder(); }
  var q={}; try{ location.search.replace(/^\?/,'').split('&').forEach(function(p){ if(!p) return; var kv=p.split('='); q[decodeURIComponent(kv[0])]=(kv[1]&&decodeURIComponent(kv[1].replace(/\+/g,' ')))||''; }); }catch(x){}
  var st=(q.status||q.payment_status||'').toLowerCase();
  document.getElementById('okNum').textContent=order.num;
  document.getElementById('okDate').textContent=order.date;
  document.getElementById('okSum').textContent=order.price?order.ptxt:'без оплаты';
  var h=document.querySelector('.ok-hero h2');
  var way=document.getElementById('okWay');
  if(st==='canceled'||st==='cancelled'||st==='failed'){
    if(h) h.textContent='Оплата не завершена';
    if(way) way.textContent='Платёж отменён или не прошёл. Вы можете вернуться и оформить заказ ещё раз, либо написать на sales@mayak-legal.ru.';
    return;
  }
  if(st==='pending'||st==='waiting_for_capture'){
    if(h) h.textContent='Ожидаем подтверждение оплаты';
    if(way) way.textContent='ЮKassa ещё подтверждает платёж. Обычно это занимает несколько минут. Чек и результат придут '+order.way+'.';
    return;
  }
  if(way) way.textContent='«'+order.name+'». Результат работ придёт '+order.way+
    ' в срок, указанный для этой услуги. Чек придёт на почту в течение рабочего дня.';
  if(h) h.textContent=order.price?'Оплата прошла, заказ принят':'Заказ принят';
}
document.addEventListener('click',function(e){
  var payBtn=e.target.closest('#coPay');
  if(!payBtn) return;
  e.preventDefault();
  if(!order){ alert('Заказ не найден. Оформите заявку заново.'); return; }
  if(order.case_id){
    var prev=payBtn.innerHTML;
    function setBusy(on,label){
      payBtn.disabled=!!on;
      if(on) payBtn.textContent=label||'Оплата…';
      else payBtn.innerHTML=prev;
    }
    setBusy(true, 'Оплата…');
    waitForPayment(order.case_id, setBusy).then(applyPaymentResult).catch(function(err){
      setBusy(false);
      alert(((err&&err.message)||'Не удалось перейти к оплате')+'\n\nПопробуйте ещё раз или напишите на sales@mayak-legal.ru');
    });
    return;
  }
  // Платные услуги без Estate API пока макет
  if(order.price>0){
    alert('Онлайн-оплата для этой услуги скоро будет доступна. Напишите на sales@mayak-legal.ru — оформим заказ вручную.');
    return;
  }
  go('success',true);
});

