/* ============ РОУТЕР: Vite MPA (slashless) ============ */
var SVCP={property:1,build:1};
var URLS={home:'/',about:'/about/',property:'/property/',build:'/build/',
 realtors:'/realtors/',reports:'/reports/',faq:'/faq/',blog:'/blog/',
 contacts:'/contacts/',legal:'/legal/',pay:'/pay/',account:'/account/',
 checkout:'/checkout/',success:'/payment/result/',unsubscribe:'/unsubscribe/',e404:'/404/'};
function here(){
  var p=(location.pathname||'/').replace(/\/+$/,'')||'/';
  if(p==='/'||p==='/index.html') return 'home';
  if(p==='/payment/result'||p==='/success') return 'success';
  for(var k in URLS){
    if(k==='home') continue;
    var u=URLS[k].replace(/\/+$/,'');
    if(p===u||p===u+'.html') return k;
  }
  return 'e404';
}
function go(id,push){
  if(id===here()){ init(id); return; }
  var u=URLS[id]||'/';
  flash(function(){ location.href=u; });
}
window.go=go;
function init(id){
  if(id==='checkout') drawCheckout();
  if(id==='success') drawSuccess();
  if(id==='faq') initFaq();
  if(id==='blog') initBlog();
  if(id==='home'){ initSea(); drawPicker(); }
  if(id==='property'||id==='build') initMaps();

  document.querySelectorAll('.nav a,.drop a,.foot-nav a,.nav-hi').forEach(function(a){
    var h=a.getAttribute('href')||'';
    var on=false;
    if(id==='home') on=(h==='/'||h==='');
    else {
      var want=URLS[id]||'';
      on=h===want||h===want.replace(/\/$/,'');
    }
    a.classList.toggle('on',on);
  });
  var np=document.getElementById('navSvc'); if(np) np.classList.toggle('on',!!SVCP[id]);
  var t=document.querySelector('main .page'); if(t) t.hidden=false;
  observe(document);
}
